#!/usr/bin/env bash
# SPDX-License-Identifier: LicenseRef-zkasuran-SAND-1.0
set -euo pipefail
ROOT="$(dirname "$0")"
# The same source gate runs locally and in the public workflow. Tests explicitly
# isolate laptop-only negative controls from the runner's ambient context.
PYTHONDONTWRITEBYTECODE=1 python3 -W error -c 'from pathlib import Path; import sys; root=Path(sys.argv[1]); required=("LICENSE","NOTICE","DATA-SOURCES.md","SECURITY.md","ready_contract.py","test_ready_contract.py","expand_proposals.py","proposal_matching.py","test_expand_proposals.py","heldout_freeze.py","serving_contract.py","serve.py","test_serving.py"); missing=[p for p in required if not (root/p).is_file()]; assert not missing, missing; print("Standalone rights, threat-model and source-contract files PASS")' "$ROOT"
PYTHONDONTWRITEBYTECODE=1 python3 -W error -c 'from pathlib import Path; import sys; paths=list(Path(sys.argv[1]).glob("*.py")); [compile(p.read_text(), str(p), "exec") for p in paths]; print("Python compilation PASS:", len(paths), "files")' "$ROOT"
PYTHONDONTWRITEBYTECODE=1 python3 -W error -m unittest discover -s "$ROOT" -p 'test_*.py' -v
PYTHONDONTWRITEBYTECODE=1 python3 -W error -c 'import sys; sys.path.insert(0,sys.argv[1]); from trainer_contract import trainer_pairs; r={"prompt":"synthetic-only","chosen":"synthetic-alpha","rejected":"synthetic-beta"}; p=trainer_pairs([r])[0]; assert p["margin"]==0.0 and all(p[k]==r[k] for k in r); print("Primary trainer loader-shape contract PASS, no neural imports")' "$ROOT"
PYTHONDONTWRITEBYTECODE=1 python3 -W error -c 'import sys; sys.path.insert(0,sys.argv[1]); from artifact_layout import validate_names; validate_names(["candidate.json","foundation.json","frozen-baselines.json","KEYWORD_EXTRACTION.safetensors","KEYWORD_EXTRACTION_INITIAL.safetensors"],"train",True); validate_names(["registration-ready.json","audit-result.json"],"audit",True); print("Literal producer/consumer artifact layout contract PASS")' "$ROOT"
PYTHONDONTWRITEBYTECODE=1 python3 -W error -c 'import sys; from pathlib import Path; sys.path.insert(0,sys.argv[1]); from remote import approved_data; from gates import structural_source_gate; p=Path(sys.argv[1])/"approved"; r=p/"approved-manifest.json"; data=approved_data(p) if r.exists() else None; gate=structural_source_gate(data[1]["train"]) if data else None; assert gate is None or gate["ok"], gate; print("Packaged source dataset and primary structural thresholds PASS" if data else "No packaged approved dataset; neural dispatch remains refused")' "$ROOT"
printf '%s\n' 'LOCAL SOURCE AND LEXICAL CHECKS PASS. Neural candidate and node qualification remain unverified.'
